        public void Push(ValueTuple<T1, T2, T3, T4, T5, T6, T7, TRest> value, ValuePusher pusher)
        {
            using var tuplePusher = pusher.PushRecord();
            PushElements(value, tuplePusher);
        }

        public void PushElements(ValueTuple<T1, T2, T3, T4, T5, T6, T7, TRest> value, ValuePusher pusher)
        {
            FormatterProvider.GetFormatter<T1>().Push(value.Item1, pusher);
            FormatterProvider.GetFormatter<T2>().Push(value.Item2, pusher);
            FormatterProvider.GetFormatter<T3>().Push(value.Item3, pusher);
            FormatterProvider.GetFormatter<T4>().Push(value.Item4, pusher);
            FormatterProvider.GetFormatter<T5>().Push(value.Item5, pusher);
            FormatterProvider.GetFormatter<T6>().Push(value.Item6, pusher);
            FormatterProvider.GetFormatter<T7>().Push(value.Item7, pusher);
            TupleElements.Push(value.Rest, pusher);
        }
    }
}
